import{_ as t,o as a,c as s,ao as o}from"./chunks/framework.GLD05vDx.js";const m=JSON.parse('{"title":"Spectral Views","description":"","frontmatter":{},"headers":[],"relativePath":"developers/spectra.md","filePath":"developers/spectra.md","lastUpdated":null}'),n={name:"developers/spectra.md"};function r(i,e,l,d,c,p){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="Spectral-Views" tabindex="-1">Spectral Views <a class="header-anchor" href="#Spectral-Views" aria-label="Permalink to &quot;Spectral Views {#Spectral-Views}&quot;">​</a></h1><p>Pick a spectral view in TKApp&#39;s <strong>View</strong> menu to spot noise, mains harmonics or a dead sensor that a trace hides.</p><table tabindex="0"><thead><tr><th style="text-align:left;">View</th><th style="text-align:left;">What you get</th></tr></thead><tbody><tr><td style="text-align:left;"><code>Time | Spectra</code></td><td style="text-align:left;">a PSD panel next to each trace</td></tr><tr><td style="text-align:left;"><code>Spectra</code></td><td style="text-align:left;">the same PSD panels at full width, no traces</td></tr></tbody></table><p><strong>Window</strong> and <strong>Scroll</strong> choose the samples, masks remove theirs, and the spectra update as soon as you mask or unmask. The line below the plots shows <code>nfft</code>, <code>df = fs/nfft</code>, Nyquist, segment length and segment count; the <strong>i</strong> badge explains each term.</p><h2 id="How-the-spectra-are-computed" tabindex="-1">How the spectra are computed <a class="header-anchor" href="#How-the-spectra-are-computed" aria-label="Permalink to &quot;How the spectra are computed {#How-the-spectra-are-computed}&quot;">​</a></h2><p>Welch&#39;s method on the visible window:</p><ol><li><p>Masked samples are <strong>removed, not zero-filled</strong>, which leaves good stretches. A gap between joined runs (e.g. high-rate Metronix) also ends a stretch, so no segment spans two recordings.</p></li><li><p>Each stretch is cut into <code>nfft</code>-sample segments with 50% overlap. Leftovers shorter than <code>nfft</code> are dropped.</p></li><li><p>Each segment: remove the mean, apply a Hann window <code>w</code>, FFT, scale <code>|X(f)|²</code> by <code>1 / (fs · Σ w²)</code>, double all bins except 0 Hz and Nyquist. The result is a one-sided PSD in amplitude²/Hz.</p></li><li><p>Average all segments with equal weight.</p></li></ol><p>Both axes are logarithmic. The 0 Hz bin is hidden, and the y axis shows at most eight decades below the peak.</p><h2 id="How-the-transform-length-is-selected" tabindex="-1">How the transform length is selected <a class="header-anchor" href="#How-the-transform-length-is-selected" aria-label="Permalink to &quot;How the transform length is selected {#How-the-transform-length-is-selected}&quot;">​</a></h2><p><code>nfft</code> = window length in samples ÷ 8, rounded down to a power of two, clamped to <code>[256, 8192]</code> (8192 for <code>All</code>). Widen the window for finer frequency resolution, narrow it for finer time resolution. If no stretch is as long as <code>nfft</code>, the panel says so: widen the window or remove a mask.</p><h2 id="Performance" tabindex="-1">Performance <a class="header-anchor" href="#Performance" aria-label="Permalink to &quot;Performance {#Performance}&quot;">​</a></h2><p>Workspaces (taper, FFT plan, buffers) are cached by <code>(nfft, fs, noverlap, window, detrend)</code>, and a short timer delays recomputation while you scroll.</p><div class="tip custom-block"><p class="custom-block-title">Internal API</p><p><code>Timekeepers._welch_psd</code>, <code>Timekeepers._welch_psd_segments</code> and <code>Timekeepers.SpectralWorkspace</code> are internal and may change. For your own spectral analysis, get clean segments and use a dedicated package:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">segments </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> good_segments</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ta, mask; min_samples </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4096</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div></div>',13)])])}const g=t(n,[["render",r]]);export{m as __pageData,g as default};
